window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b8cc5c2834dd3832"]={"versions": [{"id": "FIG-b8cc5c2834dd3832", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklassen &amp; Metamodell-Eigenschaften</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Wurzel für alle Port-Schnittstellen in AUTOSAR.\n</li><li>Typisiert als <code>ARElement</code> (erstklassiges, im ARXML-Paketbaum eigenständig referenzierbares Modellierungselement).\n</li><li>Stereotypen/Attribute: <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> (kann als Blueprint-Schablone definiert und abgeleitet werden), <code>«AtpType»</code> (fungiert als Schnittstellentyp für PortPrototypes).\n</li></ul>\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>PortInterface</code>.\n</li><li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im Adaptive Service- bzw. Komponentenmodell.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</h5>\n<p class=\"fig-p\">Alle Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände:</p>\n<ol class=\"fig-list\"><li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).\n</li><li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).\n</li><li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2, Pin- oder Wake-Up-basiert).\n</li><li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts/Fahrzeugs.\n</li><li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><strong>Aktivierung &amp; Sockets (Activation Line):</strong>\n<ul class=\"fig-list\"><li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.\n</li><li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.\n</li><li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.\n</li></ul>\n</li><li><strong>Vehicle Announcement:</strong>\n<ul class=\"fig-list\"><li>Nach Verbindungsaufbau (Link-Up/DHCP) oder getriggert via <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> sendet der DoIP-Stack bis zu 3x die Vehicle Announcement Message (VAM) an den Multicast-/Broadcast-Port 13400.\n</li></ul>\n</li><li><strong>Statusabfragen (Power Mode &amp; Group ID):</strong>\n<ul class=\"fig-list\"><li>Geht ein DoIP-Request (z. B. <em>Power Mode Information Request</em>) vom Tester ein, ruft der Stack synchron/asynchron über das <code>DiagnosticDoIPPowerModeInterface</code> den Zustand beim Platform State Management ab und formuliert die DoIP-Response.\n</li><li>Bei Gruppenzuordnung greift der Stack über das <code>DiagnosticDoIPGroupIdentificationInterface</code> auf hinterlegte Routing-Parameter zu.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Modellierung (ARXML):</strong>\n<ul class=\"fig-list\"><li>Ports an <code>AdaptiveApplication</code>s oder Plattform-Daemons müssen explizit mit einer dieser Schnittstellen typisiert werden (<code>provided</code> oder <code>required PortPrototype</code>).\n</li><li>Ein Service Instance Manifest mappt diese Port-Interfaces auf ara::com-Services oder plattforminterne direkte IPC-Bindings des Diagnostic Managers (DM).\n</li></ul>\n</li><li><strong>API- &amp; C++-Stack-Vertrag (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Implementierende Komponenten stellen Callback-Klassen bzw. Observer bereit, die den Schnittstellenfunktionalitäten entsprechen (z. B. Abfrage-Methoden für Power Mode oder Events für Statusänderungen der Activation Line).\n</li><li>Fehlende oder inkorrekte Port-Definitionen im Execution Manifest verhindern das standardkonforme Starten des DoIP-Daemons bzw. führen zur Verweigerung von ISO 13400-Konformitätstests.\n</li></ul>\n</li><li><strong>Systemintegration:</strong>\n<ul class=\"fig-list\"><li>Entwickler von State Management und I/O-Basissoftware müssen zwingend das <code>DiagnosticDoIPActivationLineInterface</code> bedienen, um DoIP normgerecht (Batterieschutz bei ausgeschalteter Zündung) freizugeben oder schlafen zu legen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-35b7b7ef71de12fe", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklassen &amp; Metamodell-Eigenschaften</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Wurzel für alle Port-Schnittstellen in AUTOSAR.\n</li><li>Typisiert als <code>ARElement</code> (erstklassiges, im ARXML-Paketbaum eigenständig referenzierbares Modellierungselement).\n</li><li>Stereotypen/Attribute: <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> (kann als Blueprint-Schablone definiert und abgeleitet werden), <code>«AtpType»</code> (fungiert als Schnittstellentyp für PortPrototypes).\n</li></ul>\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>PortInterface</code>.\n</li><li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im Adaptive Service- bzw. Komponentenmodell.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</h5>\n<p class=\"fig-p\">Alle Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände:</p>\n<ol class=\"fig-list\"><li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).\n</li><li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).\n</li><li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2, Pin- oder Wake-Up-basiert).\n</li><li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts/Fahrzeugs.\n</li><li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><strong>Aktivierung &amp; Sockets (Activation Line):</strong>\n<ul class=\"fig-list\"><li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.\n</li><li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.\n</li><li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.\n</li></ul>\n</li><li><strong>Vehicle Announcement:</strong>\n<ul class=\"fig-list\"><li>Nach Verbindungsaufbau (Link-Up/DHCP) oder getriggert via <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> sendet der DoIP-Stack bis zu 3x die Vehicle Announcement Message (VAM) an den Multicast-/Broadcast-Port 13400.\n</li></ul>\n</li><li><strong>Statusabfragen (Power Mode &amp; Group ID):</strong>\n<ul class=\"fig-list\"><li>Geht ein DoIP-Request (z. B. <em>Power Mode Information Request</em>) vom Tester ein, ruft der Stack synchron/asynchron über das <code>DiagnosticDoIPPowerModeInterface</code> den Zustand beim Platform State Management ab und formuliert die DoIP-Response.\n</li><li>Bei Gruppenzuordnung greift der Stack über das <code>DiagnosticDoIPGroupIdentificationInterface</code> auf hinterlegte Routing-Parameter zu.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Modellierung (ARXML):</strong>\n<ul class=\"fig-list\"><li>Ports an <code>AdaptiveApplication</code>s oder Plattform-Daemons müssen explizit mit einer dieser Schnittstellen typisiert werden (<code>provided</code> oder <code>required PortPrototype</code>).\n</li><li>Ein Service Instance Manifest mappt diese Port-Interfaces auf ara::com-Services oder plattforminterne direkte IPC-Bindings des Diagnostic Managers (DM).\n</li></ul>\n</li><li><strong>API- &amp; C++-Stack-Vertrag (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Implementierende Komponenten stellen Callback-Klassen bzw. Observer bereit, die den Schnittstellenfunktionalitäten entsprechen (z. B. Abfrage-Methoden für Power Mode oder Events für Statusänderungen der Activation Line).\n</li><li>Fehlende oder inkorrekte Port-Definitionen im Execution Manifest verhindern das standardkonforme Starten des DoIP-Daemons bzw. führen zur Verweigerung von ISO 13400-Konformitätstests.\n</li></ul>\n</li><li><strong>Systemintegration:</strong>\n<ul class=\"fig-list\"><li>Entwickler von State Management und I/O-Basissoftware müssen zwingend das <code>DiagnosticDoIPActivationLineInterface</code> bedienen, um DoIP normgerecht (Batterieschutz bei ausgeschalteter Zündung) freizugeben oder schlafen zu legen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-230ed2690c04d519", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklassen &amp; Metamodell-Eigenschaften</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.\n</li><li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert (anstatt als eigenständiges Klassenelement dargestellt).\n</li></ul>\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).\n</li><li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</h5>\n<p class=\"fig-p\">Alle Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\"><li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).\n</li><li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).\n</li><li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).\n</li><li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.\n</li><li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><strong>Aktivierung &amp; Sockets (Activation Line):</strong>\n<ul class=\"fig-list\"><li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.\n</li><li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.\n</li><li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.\n</li></ul>\n</li><li><strong>Vehicle Announcement:</strong>\n<ul class=\"fig-list\"><li>Nach Verbindungsaufbau (Link-Up/DHCP) oder getriggert via <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> sendet der DoIP-Stack bis zu 3x die Vehicle Announcement Message (VAM) an den Multicast-/Broadcast-Port 13400.\n</li></ul>\n</li><li><strong>Statusabfragen (Power Mode &amp; Group ID):</strong>\n<ul class=\"fig-list\"><li>Geht ein DoIP-Request (z. B. <em>Power Mode Information Request</em>) vom Tester ein, ruft der Stack synchron/asynchron über das <code>DiagnosticDoIPPowerModeInterface</code> den Zustand beim Platform State Management ab und formuliert die DoIP-Response.\n</li><li>Bei Gruppenzuordnung greift der Stack über das <code>DiagnosticDoIPGroupIdentificationInterface</code> auf hinterlegte Routing-Parameter zu.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Modellierung (ARXML):</strong>\n<ul class=\"fig-list\"><li>Ports an <code>AdaptiveApplication</code>s oder Plattform-Daemons müssen explizit mit einer dieser Schnittstellen typisiert werden (<code>provided</code> oder <code>required PortPrototype</code>).\n</li><li>Ein Service Instance Manifest mappt diese Port-Interfaces auf ara::com-Services oder plattforminterne direkte IPC-Bindings des Diagnostic Managers (DM).\n</li></ul>\n</li><li><strong>API- &amp; C++-Stack-Vertrag (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Implementierende Komponenten stellen Callback-Klassen bzw. Observer bereit, die den Schnittstellenfunktionalitäten entsprechen (z. B. Abfrage-Methoden für Power Mode oder Events für Statusänderungen der Activation Line).\n</li><li>Fehlende oder inkorrekte Port-Definitionen im Execution Manifest verhindern das standardkonforme Starten des DoIP-Daemons bzw. führen zur Verweigerung von ISO 13400-Konformitätstests.\n</li></ul>\n</li><li><strong>Systemintegration:</strong>\n<ul class=\"fig-list\"><li>Entwickler von State Management und I/O-Basissoftware müssen zwingend das <code>DiagnosticDoIPActivationLineInterface</code> bedienen, um DoIP normgerecht (Batterieschutz bei ausgeschalteter Zündung) freizugeben oder schlafen zu legen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f4a45266422dbccd", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklassen &amp; Metamodell-Eigenschaften</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.\n</li><li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert.\n</li></ul>\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).\n</li><li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</h5>\n<p class=\"fig-p\">Alle fünf Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\"><li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).\n</li><li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPEntityIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Bereitstellung und Ermittlung von DoIP-Entitätsidentifikationsdaten (<em>Entity Identification</em>, EID / VIN).\n</li><li>Erlaubt dem DoIP-Daemon die Abfrage von Identifikationsparametern zur Beantwortung von <em>DoIP Entity Identification Requests</em> bzw. zur Zusammensetzung von Identifikationsmeldungen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).\n</li><li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).\n</li><li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.\n</li><li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><strong>Aktivierung &amp; Sockets (Activation Line):</strong>\n<ul class=\"fig-list\"><li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.\n</li><li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.\n</li><li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.\n</li></ul>\n</li><li><strong>Fahrzeugankündigung &amp; Trigger (Vehicle Announcement):</strong>\n<ul class=\"fig-list\"><li>Nach Verbindungsaufbau oder getriggert über <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> versendet der DoIP-Daemon initiale <em>Vehicle Announcement Messages</em> via UDP-Broadcast/Multicast.\n</li></ul>\n</li><li><strong>Entitäts- &amp; Gruppenidentifikation (Entity &amp; Group Identification):</strong>\n<ul class=\"fig-list\"><li>Bei Eingang von <em>DoIP Entity Identification Requests</em> externer DoIP-Tester fragt der DoIP-Daemon dynamisch die Entitätsdaten (z. B. VIN, EID) über <code>DiagnosticDoIPEntityIdentificationInterface</code> ab.\n</li><li>Die logische Zuordnung und Gruppenidentifikation wird parallel über <code>DiagnosticDoIPGroupIdentificationInterface</code> bezogen.\n</li></ul>\n</li><li><strong>Energiemodus-Status (Power Mode):</strong>\n<ul class=\"fig-list\"><li>Bei Erhalt eines <em>Diagnostic Power Mode Information Request</em> fragt der DoIP-Daemon den aktuellen Energiemodus über <code>DiagnosticDoIPPowerModeInterface</code> ab und übermittelt diesen an den Tester.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Erweiterung:</strong> Mit der Einführung von <code>DiagnosticDoIPEntityIdentificationInterface</code> wird die Modellierung der DoIP-Identifikation vervollständigt. Neben der Gruppenidentifikation (GID) kann nun auch die spezifische Entitätsidentifikation (EID, VIN) über typisierte Port-Schnittstellen softwaregetrieben angebunden werden.\n</li><li><strong>Entwickler-Hinweise:</strong> Entwickler können DoIP-Entitätsparameter flexibel gestalten; anstatt VIN und EID rein statisch im Diagnostic Manifest zu hinterlegen, ermöglicht das Interface eine dynamische Bereitstellung zur Laufzeit.\n</li><li><strong>Port-Typisierung:</strong> Sämtliche Subklassen fungieren als Schnittstellentypen für <code>ProvidedPortPrototype</code> oder <code>RequiredPortPrototype</code> am Diagnostic Management bzw. den anbindenden Adaptive Applications.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8f9fc59e91e52ccb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklassen &amp; Metamodell-Eigenschaften</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.\n</li><li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert.\n</li></ul>\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).\n</li><li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</h5>\n<p class=\"fig-p\">Alle fünf Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\"><li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).\n</li><li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPEntityIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Bereitstellung und Ermittlung von DoIP-Entitätsidentifikationsdaten (<em>Entity Identification</em>, EID / VIN).\n</li><li>Erlaubt dem DoIP-Daemon die Abfrage von Identifikationsparametern zur Beantwortung von <em>DoIP Entity Identification Requests</em> bzw. zur Zusammensetzung von Identifikationsmeldungen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).\n</li><li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).\n</li><li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.\n</li><li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><strong>Aktivierung &amp; Sockets (Activation Line):</strong>\n<ul class=\"fig-list\"><li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.\n</li><li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.\n</li><li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.\n</li></ul>\n</li><li><strong>Fahrzeugankündigung &amp; Trigger (Vehicle Announcement):</strong>\n<ul class=\"fig-list\"><li>Nach Verbindungsaufbau oder getriggert über <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> versendet der DoIP-Daemon initiale <em>Vehicle Announcement Messages</em> via UDP-Broadcast/Multicast.\n</li></ul>\n</li><li><strong>Entitäts- &amp; Gruppenidentifikation (Entity &amp; Group Identification):</strong>\n<ul class=\"fig-list\"><li>Bei Eingang von <em>DoIP Entity Identification Requests</em> externer DoIP-Tester fragt der DoIP-Daemon dynamisch die Entitätsdaten (z. B. VIN, EID) über <code>DiagnosticDoIPEntityIdentificationInterface</code> ab.\n</li><li>Die logische Zuordnung und Gruppenidentifikation wird parallel über <code>DiagnosticDoIPGroupIdentificationInterface</code> bezogen.\n</li></ul>\n</li><li><strong>Energiemodus-Status (Power Mode):</strong>\n<ul class=\"fig-list\"><li>Bei Erhalt eines <em>Diagnostic Power Mode Information Request</em> fragt der DoIP-Daemon den aktuellen Energiemodus über <code>DiagnosticDoIPPowerModeInterface</code> ab und übermittelt diesen an den Tester.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Erweiterung:</strong> Mit der Einführung von <code>DiagnosticDoIPEntityIdentificationInterface</code> wird die Modellierung der DoIP-Identifikation vervollständigt. Neben der Gruppenidentifikation (GID) kann nun auch die spezifische Entitätsidentifikation (EID, VIN) über typisierte Port-Schnittstellen softwaregetrieben angebunden werden.\n</li><li><strong>Entwickler-Hinweise:</strong> Entwickler können DoIP-Entitätsparameter flexibel gestalten; anstatt VIN und EID rein statisch im Diagnostic Manifest zu hinterlegen, ermöglicht das Interface eine dynamische Bereitstellung zur Laufzeit.\n</li><li><strong>Port-Typisierung:</strong> Sämtliche Subklassen fungieren als Schnittstellentypen für <code>ProvidedPortPrototype</code> oder <code>RequiredPortPrototype</code> am Diagnostic Management bzw. den anbindenden Adaptive Applications.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ff99f5293c2da583", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basisklassen &amp; Metamodell-Eigenschaften</h5>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.\n</li><li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert.\n</li></ul>\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).\n</li><li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</h5>\n<p class=\"fig-p\">Alle fünf Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\"><li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).\n</li><li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPEntityIdentificationInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Schnittstelle zur dynamischen Bereitstellung und Ermittlung von DoIP-Entitätsidentifikationsdaten (<em>Entity Identification</em>, EID / VIN).\n</li><li>Erlaubt dem DoIP-Daemon die Abfrage von Identifikationsparametern zur Beantwortung von <em>DoIP Entity Identification Requests</em> bzw. zur Zusammensetzung von Identifikationsmeldungen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).\n</li><li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).\n</li><li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.\n</li></ul>\n</li><li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong>\n<ul class=\"fig-list\"><li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.\n</li><li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><strong>Aktivierung &amp; Sockets (Activation Line):</strong>\n<ul class=\"fig-list\"><li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.\n</li><li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.\n</li><li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.\n</li></ul>\n</li><li><strong>Fahrzeugankündigung &amp; Trigger (Vehicle Announcement):</strong>\n<ul class=\"fig-list\"><li>Nach Verbindungsaufbau oder getriggert über <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> versendet der DoIP-Daemon initiale <em>Vehicle Announcement Messages</em> via UDP-Broadcast/Multicast.\n</li></ul>\n</li><li><strong>Entitäts- &amp; Gruppenidentifikation (Entity &amp; Group Identification):</strong>\n<ul class=\"fig-list\"><li>Bei Eingang von <em>DoIP Entity Identification Requests</em> externer DoIP-Tester fragt der DoIP-Daemon dynamisch die Entitätsdaten (z. B. VIN, EID) über <code>DiagnosticDoIPEntityIdentificationInterface</code> ab.\n</li><li>Die logische Zuordnung und Gruppenidentifikation wird parallel über <code>DiagnosticDoIPGroupIdentificationInterface</code> bezogen.\n</li></ul>\n</li><li><strong>Energiemodus-Status (Power Mode):</strong>\n<ul class=\"fig-list\"><li>Bei Erhalt eines <em>Diagnostic Power Mode Information Request</em> fragt der DoIP-Daemon den aktuellen Energiemodus über <code>DiagnosticDoIPPowerModeInterface</code> ab und übermittelt diesen an den Tester.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Erweiterung:</strong> Mit der Einführung von <code>DiagnosticDoIPEntityIdentificationInterface</code> wird die Modellierung der DoIP-Identifikation vervollständigt. Neben der Gruppenidentifikation (GID) kann nun auch die spezifische Entitätsidentifikation (EID, VIN) über typisierte Port-Schnittstellen softwaregetrieben angebunden werden.\n</li><li><strong>Entwickler-Hinweise:</strong> Entwickler können DoIP-Entitätsparameter flexibel gestalten; anstatt VIN und EID rein statisch im Diagnostic Manifest zu hinterlegen, ermöglicht das Interface eine dynamische Bereitstellung zur Laufzeit.\n</li><li><strong>Port-Typisierung:</strong> Sämtliche Subklassen fungieren als Schnittstellentypen für <code>ProvidedPortPrototype</code> oder <code>RequiredPortPrototype</code> am Diagnostic Management bzw. den anbindenden Adaptive Applications.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b8cc5c2834dd3832", "to": "FIG-35b7b7ef71de12fe", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-35b7b7ef71de12fe", "to": "FIG-230ed2690c04d519", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>PortInterface</code>: Die eigenständige Klassendarstellung mit den Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sowie die Vererbungskante wurden entfernt; <code>PortInterface</code> wird stattdessen als Superklasse in der oberen rechten Ecke von <code>DiagnosticPortInterface</code> referenziert.\n</li></ul>"}, {"from": "FIG-230ed2690c04d519", "to": "FIG-f4a45266422dbccd", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticDoIPEntityIdentificationInterface</code>: Neue Schnittstellenklasse als Spezialisierung von <code>DiagnosticPortInterface</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-f4a45266422dbccd", "to": "FIG-8f9fc59e91e52ccb", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8f9fc59e91e52ccb", "to": "FIG-ff99f5293c2da583", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
